// ─── EV: Compute Metrics — score system output against an adjudicated gold ───
// gap 3: axis-level agreement + exact-match vs off-by-one on the final code
// gap 2: feed accumulated results from here to calibrate the confidence threshold
const b = $input.first().json.body || $input.first().json;
const sug = b.suggested || {}; const gold = b.gold || {};
const CODE_RANK = {'99281':0,'99282':1,'99283':2,'99284':3,'99285':4};
const lvl = (x) => x==null ? null : String(x.level!==undefined?x.level:x).toLowerCase();

const sa = sug.axes||{}, ga = gold.axes||{};
const axisResults=[]; let match=0, tot=0;
for (const k of ['axis1','axis2','axis3']) {
  const s = lvl(sa[k]), g = lvl(ga[k]);
  if (s && g) { tot++; const m = s===g; if(m) match++; axisResults.push({axis:k, suggested:s, gold:g, match:m}); }
}
const sc = sug.code || sug.finalCode || '';
const gc = gold.code || '';
const exactMatch = (sc && gc) ? (sc===gc) : null;
let offByOne = null;
if (sc in CODE_RANK && gc in CODE_RANK) offByOne = Math.abs(CODE_RANK[sc]-CODE_RANK[gc]) <= 1;
return [{ json: {
  ts: new Date().toISOString(), patientId: b.patientId||'',
  axisResults, axisMatched: match, axisTotal: tot,
  axisAgreement: tot ? match/tot : null,
  suggestedCode: sc, goldCode: gc, exactMatch, offByOne
} }];

// ─── CN: Verify + Reconcile ──────────────────────────────────────────────────
// gap 1: drop MDM citations not present in the source; lower that axis confidence
// gap 4b: compare two independent scorers; disagreement also lowers confidence
// so the existing 0.75 gate routes ungrounded OR contested axes to a human query
function extractRawText(inp){
  if(Array.isArray(inp.output)){for(const m of inp.output){if(Array.isArray(m.content)){for(const b of m.content){if(b.text)return b.text;}}if(typeof m.text==='string')return m.text;}}
  if(inp.message&&inp.message.content) return inp.message.content;
  if(Array.isArray(inp.choices)&&inp.choices[0]&&inp.choices[0].message&&inp.choices[0].message.content) return inp.choices[0].message.content;
  if(typeof inp.text==='string')return inp.text;
  if(typeof inp.content==='string')return inp.content;
  if(typeof inp.output==='string')return inp.output;
  return JSON.stringify(inp);
}
function parseAxes(node){
  try { const raw = extractRawText(node).replace(/```json|```/g,'').trim();
    const s=raw.indexOf('{'), e=raw.lastIndexOf('}');
    return JSON.parse(s!==-1&&e>s?raw.substring(s,e+1):raw).axes; } catch(e){ return null; }
}
const norm = (s) => String(s==null?'':s)
  .replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/gi,' ')
  .replace(/[\u2018\u2019\u201c\u201d]/g,"'").replace(/\s+/g,' ').trim().toLowerCase();

const A = parseAxes($('CN: Score E/M').first().json);          // primary scorer
const B = parseAxes($('CN: Score E/M B').first().json);        // second scorer
const prep = $('CN: Parse Faithfulness').first().json;
const source = norm((prep.soapHtml||'') + ' ' + (prep.transcript||''));
const THRESHOLD = 0.75;

let citTotal=0, citVerified=0; const adjusted=[]; const agreement=[];
if (A) {
  for (const k of ['axis1','axis2','axis3']) {
    const a = A[k]; if (!a) continue;
    // citation grounding
    const cites = Array.isArray(a.citations) ? a.citations : [];
    const kept=[]; let dropped=0;
    for (const q of cites) { citTotal++; const nq=norm(q);
      if (nq.length>=8 && source.includes(nq)) { citVerified++; kept.push(q); } else dropped++; }
    a.citations = kept;
    // cross-scorer agreement
    const al = String(a.level||'').toLowerCase();
    const bl = (B && B[k]) ? String(B[k].level||'').toLowerCase() : null;
    const disagree = bl ? (bl !== al) : false;
    agreement.push({ axis:k, primary:al, secondary:bl, agree: bl ? (bl===al) : null });
    // adjust confidence on either signal
    let conf = Number(a.confidence)||0; const reasons=[];
    if (dropped>0) { reasons.push(dropped+' ungrounded citation(s)'); conf = Math.min(conf, kept.length===0?0.4:0.6); }
    if (disagree) { reasons.push('scorer disagreement ('+al+' vs '+bl+')'); conf = Math.min(conf, 0.5); }
    if (reasons.length) { a.confidence = conf; adjusted.push({ axis:k, newConfidence:conf, reasons }); }
  }
}
const faith = prep.faithfulness || {};
const agreed = agreement.filter(x=>x.agree===true).length;
const comparable = agreement.filter(x=>x.agree!==null).length;
const validation = {
  faithful: (faith.faithful!==undefined?faith.faithful:null),
  faithScore: (faith.score!==undefined?faith.score:null),
  unsupported: Array.isArray(faith.unsupported)?faith.unsupported:[],
  citationsTotal: citTotal, citationsVerified: citVerified, citationsDropped: citTotal-citVerified,
  scorerAgreement: agreement, scorerAgreed: agreed, scorerComparable: comparable,
  axesAdjusted: adjusted, threshold: THRESHOLD
};
return [{ json: { text: JSON.stringify({ axes: A || {} }), validation } }];

