  };

  const rows=keys.map(k=>{const a=axes[k]||{};const lc=color[((a.level)||'').toLowerCase()]||'#6b7280';
    const cites=(Array.isArray(a.citations)?a.citations:[]).map(q=>`<div style="font-size:11px;color:#6b7280;border-left:2px solid ${lc};padding:1px 0 1px 8px;margin:3px 0;font-style:italic">&ldquo;${esc(q)}&rdquo;</div>`).join('')||'<div style="font-size:11px;color:#9ca3af">No direct citation found</div>';
    const conf=Math.round((Number(a.confidence)||0)*100);
    return `<tr style="border-bottom:1px solid #f0f0f0">
      <td style="padding:8px 10px;font-weight:500;vertical-align:top">${labels[k]}</td>
      <td style="padding:8px 10px;vertical-align:top"><span style="background:${lc}20;color:${lc};border:1px solid ${lc}40;border-radius:4px;padding:1px 8px;font-size:11px;font-weight:700;text-transform:uppercase">${esc(a.level||'?')}</span><div style="font-size:11px;color:#6b7280;margin-top:3px">${conf}% conf</div></td>
      <td style="padding:8px 10px;vertical-align:top">${cites}</td>
    </tr>`;}).join('');

  const rangeNote = (bestCode!==docCode)
    ? `<div style="background:#fffbeb;border:1px solid #fde047;border-radius:6px;padding:8px 12px;margin:10px 0;font-size:12px;color:#854d0e">Documented now: <strong>${docCode}</strong> (${docLevel}). Up to <strong>${bestCode}</strong> (${bestLevel}) is supportable if confirmed in the note: ${uncertain.map(k=>labels[k]).join(', ')}.</div>`
    : `<div style="font-size:12px;color:#16a34a;margin:8px 0">All three axes scored with confidence; suggested code is firm.</div>`;

  emSection=`
  <div style="margin-top:18px;border-top:2px dashed #e5e7eb;padding-top:14px">
    <div style="font-size:14px;font-weight:800;color:#1e293b;margin-bottom:10px">Suggested E/M Code</div>
    <div style="background:${c}12;border:2px solid ${c};border-radius:10px;padding:14px 18px;display:flex;align-items:center;gap:16px;margin-bottom:10px">
      <div style="font-size:30px;font-weight:800;color:${c}">${docCode}</div>
      <div><div style="font-size:15px;font-weight:700;color:${c}">${docLevel.charAt(0).toUpperCase()+docLevel.slice(1)} MDM</div>
      <div style="font-size:12px;color:#6b7280">ED E/M selected by Medical Decision Making, highest 2 of 3 elements</div></div>
    </div>
    ${rangeNote}
    <div style="border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;margin-top:8px">
      <table style="width:100%;border-collapse:collapse">
        <thead><tr style="background:#f9fafb">
          <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:600">MDM ELEMENT</th>
          <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:600">LEVEL</th>
          <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:600">CITATION (from this note)</th>
        </tr></thead><tbody>${rows}</tbody>
      </table>
    </div>
    <div style="font-size:11px;color:#9ca3af;margin-top:10px;line-height:1.5">
      Code-rule source: AMA CPT 2023 Evaluation and Management (E/M) Guidelines, Emergency Department Services 99281-99285 (MDM-only; time-based coding not permitted in the ED); ACEP 2023 ED E/M Guidelines FAQ. Final MDM level to code: straightforward 99282, low 99283, moderate 99284, high 99285; 99281 does not require physician presence. Advisory only - confirm before claim submission.
    </div>
  </div>`;
} else {
  emSection=`<div style="margin-top:16px;font-size:12px;color:#9ca3af">E/M code suggestion unavailable (could not score MDM from this note).</div>`;
}

let valBanner='';
if(VAL){
  const fColor = VAL.faithful===true?'#16a34a':(VAL.faithful===false?'#dc2626':'#ca8a04');
  const fBg = VAL.faithful===true?'#f0fdf4':(VAL.faithful===false?'#fef2f2':'#fefce8');
  const fPct = (VAL.faithScore!=null)?(Math.round(VAL.faithScore*100)+'% of note claims grounded in transcript'):'note faithfulness not scored';
  const unsup = (VAL.unsupported&&VAL.unsupported.length)?`<div style=\"margin-top:4px;font-size:11px;color:${fColor}\">Unsupported: ${VAL.unsupported.slice(0,3).map(esc).join('; ')}</div>`:'';
  const citLine = `${VAL.citationsVerified}/${VAL.citationsTotal} MDM citations verified`+(VAL.citationsDropped>0?` &mdash; ${VAL.citationsDropped} dropped`:'');
  const agLine = (VAL.scorerComparable>0)?`${VAL.scorerAgreed}/${VAL.scorerComparable} axes agree across two scorers`:'single scorer';
  const flagLine = (VAL.axesAdjusted&&VAL.axesAdjusted.length)?` &mdash; ${VAL.axesAdjusted.length} axis/axes flagged for confirmation`:'';
  valBanner = `<div style=\"background:${fBg};border:1px solid ${fColor}55;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:12px;color:${fColor}\"><strong>Automated validation</strong><br>Note faithfulness: ${fPct}.<br>Citation grounding: ${citLine}.<br>Cross-scorer: ${agLine}${flagLine}.${unsup}</div>`;
}
const styledHtml = `<div style="font-family:system-ui,sans-serif;line-height:1.7;font-size:13px">
  <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px 14px;margin-bottom:14px;color:#1e40af;font-size:12px">
    📋 AI-generated SOAP note and E/M code suggestion — review before saving to chart
  </div>
  ${valBanner}
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:16px">
    ${soapBlock}
    ${emSection}
  </div>
</div>`;
return [{ json: { html: styledHtml, em, validation: VAL } }];

values.content:
You are a clinical documentation auditor. Compare the SOAP note against the consultation transcript and judge faithfulness only. A claim is unsupported if it states a clinical fact (symptom, finding, vital, diagnosis, medication, plan) not present in or following from the transcript. Do not penalize headers, formatting, or reasonable phrasing of something present. Return ONLY valid JSON, no markdown:
{ "faithful": true, "score": 0.0, "unsupported": [""], "notes": "" }
score = fraction (0..1) of note clinical claims supported by the transcript.
